import { ProcessingMode, RawRow } from '../types';

// Helper: Parse CSV string to Array of Objects
export const parseCSV = (content: string): RawRow[] => {
  const lines = content.trim().split(/\r?\n/);
  if (lines.length < 2) return [];

  // Simple CSV parser handling quotes
  const parseLine = (text: string) => {
    const result = [];
    let cur = '';
    let inQuote = false;
    for (let i = 0; i < text.length; i++) {
      const char = text[i];
      if (char === '"') {
        inQuote = !inQuote;
      } else if (char === ',' && !inQuote) {
        result.push(cur.trim());
        cur = '';
      } else {
        cur += char;
      }
    }
    result.push(cur.trim());
    return result.map(s => s.replace(/^"|"$/g, '').trim()); // Remove surrounding quotes
  };

  const headers = parseLine(lines[0]);
  const data = [];

  for (let i = 1; i < lines.length; i++) {
    const currentLine = parseLine(lines[i]);
    if (currentLine.length === headers.length) {
      const obj: RawRow = {};
      headers.forEach((header, index) => {
        obj[header] = currentLine[index];
      });
      data.push(obj);
    }
  }
  return data;
};

// Helper: Title Case
const toTitleCase = (str: string) => {
  if (!str) return '';
  return str.toLowerCase().split(' ').map(word => 
    word.charAt(0).toUpperCase() + word.slice(1)
  ).join(' ');
};

// Helper: Clean Gallery
const cleanGallery = (str: string) => {
  if (!str) return '';
  // Remove "Galeria", "Galeria ", extra spaces
  return str.replace(/Galeria\s?/i, '').trim();
};

// Helper: Format Phone
const formatPhone = (str: string) => {
  if (!str) return '';
  let clean = str.replace(/[^\d+]/g, '');
  if (!clean.startsWith('+')) {
    clean = '+' + clean;
  }
  return clean;
};

// Helper: Sanitize ID (Numbers only)
const sanitizeID = (str: string) => {
  if (!str) return '';
  return str.replace(/[^\d]/g, '');
};

// Helper: Find value by partial header match (robustness)
const getValue = (row: RawRow, keyPart: string): string => {
  const key = Object.keys(row).find(k => k.includes(keyPart));
  return key ? row[key] : '';
};

// Helper: Extract Time (HH:MM)
const extractTime = (row: RawRow): string => {
  // Try exact match first, then typical Google Forms columns
  let val = getValue(row, 'Horário de início');
  if (!val) val = getValue(row, 'Horário');

  if (!val) return '00:00';
  // Attempt to parse HH:MM
  const match = val.match(/(\d{1,2}):(\d{2})/);
  if (match) {
    return `${match[1].padStart(2, '0')}:${match[2]}`;
  }
  return val;
};

export const processData = (rawText: string, mode: ProcessingMode): string => {
  const data = parseCSV(rawText);
  let outputRows: string[][] = [];

  // Sort by Time
  const sortedData = [...data].sort((a, b) => {
    const timeA = extractTime(a);
    const timeB = extractTime(b);
    return timeA.localeCompare(timeB);
  });

  if (mode === ProcessingMode.VIDEOCHAMADA) {
    // 6 Columns
    outputRows = sortedData.map(row => {
      const interno = getValue(row, 'Resposta do formulário 0');
      const galeria = cleanGallery(getValue(row, 'Resposta do formulário 1'));
      const visitante = toTitleCase(getValue(row, 'Sobrenome'));
      const id = toTitleCase(getValue(row, 'Nome')); // In this mode, Nome is mapped to Matrícula/ID per prompt rules? 
      // Prompt says: 4. Matrícula/ID: Extrair da coluna 'Nome'. 
      // But prompt also says Case: Nomes Próprios. Usually ID is number, but following prompt strictly.

      const tel = formatPhone(getValue(row, 'Tel'));
      const time = extractTime(row);

      return [
        toTitleCase(interno),
        galeria,
        visitante,
        id,
        tel,
        time
      ];
    });
  } else if (mode === ProcessingMode.VISITA_INTIMA) {
    // 5 Columns
    outputRows = sortedData.map(row => {
      const interno = getValue(row, 'Resposta do formulário 0');
      const galeria = getValue(row, 'Resposta do formulário 1'); // Copy full content
      const visitante = getValue(row, 'Resposta do formulário 2');
      const id = getValue(row, 'Nome');
      const time = extractTime(row);

      return [
        toTitleCase(interno),
        galeria,
        toTitleCase(visitante),
        id,
        time
      ];
    });
  } else if (mode === ProcessingMode.VISITA_PRESENCIAL) {
    // 8 Columns
    outputRows = sortedData.map(row => {
      const interno = getValue(row, 'Resposta do formulário 0');
      const galeria = cleanGallery(getValue(row, 'Resposta do formulário 1'));
      const vis1 = getValue(row, 'Resposta do formulário 2');
      const id1 = getValue(row, 'Nome'); // Col B in prompt logic
      const vis2 = getValue(row, 'Resposta do formulário 4');
      const id2 = getValue(row, 'Resposta do formulário 5');
      const vis3 = getValue(row, 'Resposta do formulário 6');
      const id3 = getValue(row, 'Resposta do formulário 7');

      return [
        toTitleCase(interno),
        galeria,
        toTitleCase(vis1),
        sanitizeID(id1),
        vis2 ? toTitleCase(vis2) : '',
        id2 ? sanitizeID(id2) : '',
        vis3 ? toTitleCase(vis3) : '',
        id3 ? sanitizeID(id3) : ''
      ];
    });
  }

  // Convert to CSV String (no header)
  return outputRows.map(row => row.join(',')).join('\n');
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const modelId = "gemini-3-flash-preview";

export const generateDataInsights = async (csvData: string) => {
  try {
    const prompt = `
      Você é um analista de dados do sistema prisional.
      Analise o seguinte CSV de agendamentos de visitas (sem cabeçalhos).

      Os dados representam agendamentos de visitas.

      Gere um resumo curto e profissional em texto corrido (Markdown) contendo:
      1. Total de visitas agendadas.
      2. Qual galeria tem o maior volume de visitas.
      3. Qual horário de pico.
      4. Alerta se houver nomes de internos duplicados (indício de erro de agendamento).

      Dados CSV:
      ${csvData.substring(0, 10000)} // Limit to avoid token limits
    `;

    const response = await ai.models.generateContent({
      model: modelId,
      contents: prompt,
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Não foi possível gerar a análise inteligente no momento.";
  }
};

export const smartRepairCSV = async (malformedText: string): Promise<string> => {
  try {
     const prompt = `
      Você é um especialista em recuperação de dados. 
      O usuário forneceu um texto que deveria ser um CSV de agendamento, mas pode estar mal formatado (copiado de email, PDF, etc).

      Sua tarefa:
      1. Identificar padrões de: Nome do Interno, Galeria, Nome do Visitante, Documento/ID, Telefone, Horário.
      2. Transformar esse texto em um CSV limpo com os seguintes cabeçalhos EXATOS na primeira linha:
      "Carimbo de data/hora","Resposta do formulário 0","Resposta do formulário 1","Resposta do formulário 2","Nome","Sobrenome","Tel.","Horário de início do agendamento"

      Regras de Mapeamento para os cabeçalhos de saída:
      - Interno -> Resposta do formulário 0
      - Galeria -> Resposta do formulário 1
      - Visitante Principal -> Resposta do formulário 2 (ou Sobrenome, dependendo do contexto, preencha ambos se incerto)
      - Documento/Matrícula -> Nome
      - Telefone -> Tel.
      - Horário -> Horário de início do agendamento

      Retorne APENAS o bloco CSV raw, sem markdown, sem explicações.

      Texto Bruto:
      ${malformedText.substring(0, 5000)}
     `;

     const response = await ai.models.generateContent({
        model: modelId,
        contents: prompt,
     });

     const text = response.text || "";
     // Strip markdown if Gemini adds it
     return text.replace(/```csv|```/g, "").trim();

  } catch (error) {
    console.error("Smart Repair Error:", error);
    throw new Error("Falha na reparação inteligente.");
  }
}

